import java.lang.instrument.Instrumentation;import java.nio.file.*;import org.l2jmobius.gameserver.entity.World;public class LocateDust2Viewer {public static void agentmain(String dir,Instrumentation i)throws Exception{StringBuilder b=new StringBuilder();for(var p:World.getPlayers())if(p.isOnline()&&p.getClient()!=null)b.append(p.getObjectId()).append(" name=").append(p.getName()).append(" xyz=").append(p.getX()).append(",").append(p.getY()).append(",").append(p.getZ()).append(" heading=").append(p.getHeading()).append(" instance=").append(p.getInstanceId()).append("\n");Files.writeString(Path.of(dir,"viewer-location.txt"),b.toString());}}